"""Regular-language objects, pattern parsing and matching.

Patterns follow the documented Eywa grammar: a union of sequences, where a
sequence is zero or more atoms and an atom carries zero or more postfix ``*``
repetitions.  Atoms are literals, groups or non-empty character classes.
Matching is performed over Latin-1 code points with a Thompson NFA simulation,
so nested and nullable repetitions are handled without backtracking.
"""


class RegexError(Exception):
    """Raised when a pattern does not follow the documented grammar."""


class Regex(object):
    """A regular expression node; compiled lazily to an NFA for matching."""

    def __init__(self):
        self._nfa = None


class Empty(Regex):
    """A regular expression that matches the empty string."""

    def __str__(self):
        return ""


class Range(Regex):
    """A regular expression that matches one character range."""

    def __init__(self, low, high):
        Regex.__init__(self)
        if len(low) != 1 or len(high) != 1:
            raise RegexError("Range must be single characters")
        self.low = low
        self.high = high

    def __str__(self):
        return "[%s-%s]" % (self.low, self.high)


class Class(Regex):
    """A regular expression matching one character of a set of ranges."""

    def __init__(self, items):
        Regex.__init__(self)
        self.items = tuple(items)

    def __str__(self):
        return "[" + ",".join(
            "%s-%s" % (chr(low), chr(high)) for (low, high) in self.items) + "]"


class Choice(Regex):
    """A regular expression that matches a choice of regular expressions."""

    def __init__(self, *args):
        Regex.__init__(self)
        self.exprs = list(args)

    def __str__(self):
        return "(" + "|".join(str(e) for e in self.exprs) + ")"


class Seq(Regex):
    """A regular expression that matches a sequence of regular expressions."""

    def __init__(self, *args):
        Regex.__init__(self)
        self.exprs = list(args)

    def __str__(self):
        return "(" + "".join(str(e) for e in self.exprs) + ")"


class Star(Regex):
    """A regular expression that matches zero or more iterations."""

    def __init__(self, r):
        Regex.__init__(self)
        self.expr = r

    def __str__(self):
        return "(" + str(self.expr) + ")*"


def chars(low, high):
    """A regular expression that matches a character range."""
    return Range(low, high)


def empty():
    """A regular expression that matches the empty string."""
    return Empty()


def text(s):
    """A regular expression that matches an exact string."""
    if s == "":
        return empty()
    if len(s) == 1:
        return chars(s, s)
    return seq(*[chars(c, c) for c in s])


def choice(*args):
    return Choice(*args)


def seq(*args):
    return Seq(*args)


def star(r):
    return Star(r)


def plus(r):
    return seq(r, star(r))


def parse(pattern):
    """Parse a documented pattern into a regular-expression object."""
    if not isinstance(pattern, str):
        raise RegexError("pattern must be a string")
    data = pattern
    size = len(data)
    state = [0]

    def fail(reason):
        raise RegexError("%s at offset %d" % (reason, state[0]))

    def escaped():
        state[0] += 1
        if state[0] >= size:
            fail("dangling escape")
        char = data[state[0]]
        state[0] += 1
        return char

    def parse_union():
        alts = [parse_seq()]
        while state[0] < size and data[state[0]] == "|":
            state[0] += 1
            alts.append(parse_seq())
        if len(alts) == 1:
            return alts[0]
        return Choice(*alts)

    def parse_seq():
        items = []
        while state[0] < size and data[state[0]] not in "|)":
            items.append(parse_atom())
        if not items:
            return Empty()
        if len(items) == 1:
            return items[0]
        return Seq(*items)

    def parse_atom():
        node = parse_primary()
        while state[0] < size and data[state[0]] == "*":
            state[0] += 1
            node = Star(node)
        return node

    def parse_primary():
        if state[0] >= size:
            fail("truncated pattern")
        char = data[state[0]]
        if char == "(":
            state[0] += 1
            node = parse_union()
            if state[0] >= size or data[state[0]] != ")":
                fail("unclosed group")
            state[0] += 1
            return node
        if char == "[":
            return parse_class()
        if char == "*":
            fail("repetition without an atom")
        if char == ")":
            fail("unbalanced group")
        if char == "]":
            fail("unbalanced class")
        if char == "|":
            fail("union without a left alternative")
        if char == "\\":
            return Range(escaped(), escaped.__doc__ and _single(escaped))
        state[0] += 1
        return Range(char, char)

    def _single(char):
        return char

    def parse_class():
        state[0] += 1
        items = []
        while True:
            if state[0] >= size:
                fail("unclosed class")
            char = data[state[0]]
            if char == "]":
                state[0] += 1
                break
            if char == "\\":
                low = escaped()
            else:
                low = char
                state[0] += 1
            if state[0] + 1 < size and data[state[0]] == "-" and data[state[0] + 1] != "]":
                state[0] += 1
                if data[state[0]] == "\\":
                    high = escaped()
                else:
                    high = data[state[0]]
                    state[0] += 1
                items.append((ord(low), ord(high)))
            else:
                items.append((ord(low), ord(low)))
        if not items:
            fail("empty class")
        items.sort()
        merged = []
        for low, high in items:
            if low > high:
                continue
            if merged and low <= merged[-1][1] + 1:
                if high > merged[-1][1]:
                    merged[-1] = (merged[-1][0], high)
            else:
                merged.append((low, high))
        return Class(merged)

    try:
        node = parse_union()
    except RecursionError:
        raise RegexError("pattern nesting too deep")
    if state[0] != size:
        fail("unexpected trailing input")
    return node


class Nfa(object):
    """Thompson NFA for a regular expression, with memoised transitions."""

    def __init__(self, node):
        self.eps = []
        self.trans = []
        self._closure = []
        self._move = {}
        self.start, self.accept = self._build(node)

    def _new(self):
        self.eps.append([])
        self.trans.append([])
        self._closure.append(None)
        return len(self.eps) - 1

    def _build(self, node):
        if isinstance(node, Empty):
            start = self._new()
            accept = self._new()
            self.eps[start].append(accept)
            return start, accept
        if isinstance(node, Class):
            start = self._new()
            accept = self._new()
            self.trans[start].append(tuple(node.items) + (accept,))
            return start, accept
        if isinstance(node, Range):
            start = self._new()
            accept = self._new()
            self.trans[start].append(((ord(node.low), ord(node.high)), accept))
            return start, accept
        if isinstance(node, Seq):
            parts = [self._build(part) for part in node.exprs]
            if not parts:
                return self._build(Empty())
            for (_, left), (right, _) in zip(parts, parts[1:]):
                self.eps[left].append(right)
            return parts[0][0], parts[-1][1]
        if isinstance(node, Choice):
            start = self._new()
            accept = self._new()
            for alt in node.exprs:
                alt_start, alt_accept = self._build(alt)
                self.eps[start].append(alt_start)
                self.eps[alt_accept].append(accept)
            return start, accept
        if isinstance(node, Star):
            start = self._new()
            accept = self._new()
            inner_start, inner_accept = self._build(node.expr)
            self.eps[start].append(inner_start)
            self.eps[start].append(accept)
            self.eps[inner_accept].append(inner_start)
            self.eps[inner_accept].append(accept)
            return start, accept
        raise RegexError("unsupported regular-expression node")

    def closure(self, state):
        cached = self._closure[state]
        if cached is not None:
            return cached
        seen = set()
        stack = [state]
        while stack:
            item = stack.pop()
            if item in seen:
                continue
            seen.add(item)
            for target in self.eps[item]:
                if target not in seen:
                    stack.append(target)
        cached = frozenset(seen)
        self._closure[state] = cached
        return cached

    def step(self, states, char):
        code = ord(char)
        cache = self._move
        result = set()
        for state in states:
            key = (state, code)
            moved = cache.get(key)
            if moved is None:
                targets = None
                for ranges, target in self.trans[state]:
                    for low, high in ranges:
                        if low <= code <= high:
                            if targets is None:
                                targets = set()
                            targets.add(target)
                            break
                if targets:
                    merged = set()
                    for target in targets:
                        merged |= self.closure(target)
                    moved = frozenset(merged)
                else:
                    moved = frozenset()
                cache[key] = moved
            if moved:
                result |= moved
        return result


def _nfa_of(regex):
    nfa = regex._nfa
    if nfa is None:
        nfa = Nfa(regex)
        regex._nfa = nfa
    return nfa


def ismatch(r, s):
    """Determine if a string matches a regular expression (full match)."""
    if not isinstance(s, str):
        return False
    nfa = _nfa_of(r)
    current = nfa.closure(nfa.start)
    for char in s:
        if not current:
            return False
        current = nfa.step(current, char)
        if not current and nfa.accept not in current:
            return False
    return nfa.accept in current
